<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str;
class TransactionController extends Controller { public function store(Request $request) { $data=$request->validate(['service_id'=>['required','exists:services,id'],'barber_id'=>['nullable','exists:barbers,id'],'payment_method'=>['required','in:cash,gcash'],'gcash_reference_no'=>['nullable','required_if:payment_method,gcash','string','max:30']]); $barberId=$request->user()->role==='barber'?DB::table('barbers')->where('user_id',$request->user()->id)->value('id'):($data['barber_id']??null); abort_unless($barberId && ($request->user()->role==='admin'||DB::table('barbers')->where('id',$barberId)->where('user_id',$request->user()->id)->exists()),403); $total=DB::table('services')->where('id',$data['service_id'])->value('price'); DB::transaction(function() use($barberId,$data,$total) {$id=(string)Str::uuid(); DB::table('transactions')->insert(['id'=>$id,'barber_id'=>$barberId,'total_amount'=>$total,'barber_share'=>$total/2,'shop_share'=>$total/2,'created_at'=>now(),'updated_at'=>now()]); DB::table('payments')->insert(['id'=>(string)Str::uuid(),'transaction_id'=>$id,'payment_method'=>$data['payment_method'],'gcash_reference_no'=>$data['gcash_reference_no']??null,'verification_status'=>$data['payment_method']==='gcash'?'pending':'verified','amount'=>$total,'created_at'=>now(),'updated_at'=>now()]);}); return back()->with('status','Service recorded. The 50/50 earnings split was calculated automatically.'); } }
